func NewVoidEnvelopeStep[IN any](config VoidEnvelopeStepConfig[IN]) sdkgo.MutationStep[IN, VoidEnvelopeInput, VoidedEnvelope] {
	if err := config.Connection.validate(); err != nil {
		panic(err)
	}
	if config.ConnectionName != config.Connection.reference.Name {
		panic(fmt.Errorf("docusign connector Step ConnectionName %q must equal its connection's name %q", config.ConnectionName, config.Connection.reference.Name))
	}
	return sdkgo.MustNewMutationStep(sdkgo.MutationStepConfig[IN, VoidEnvelopeInput, VoidedEnvelope]{
		StepType: config.StepType, Annotations: config.Annotations,
		Operation: config.Connection.client.VoidEnvelope(), Connection: config.Connection.reference,
		MapToOperationInput: config.MapToOperationInput,
		Branches: func() []sdkgo.BranchTarget[VoidEnvelopeResult] {
			branches := make([]sdkgo.BranchTarget[VoidEnvelopeResult], 0, 6)
			if config.Voided.HasStep() {
				branches = append(branches, config.Voided.BranchTarget(VoidEnvelopeBranchVoided))
			}
			if config.NotVoidable.HasStep() {
				branches = append(branches, config.NotVoidable.BranchTarget(VoidEnvelopeBranchNotVoidable))
			}
			if config.NotFound.HasStep() {
				branches = append(branches, config.NotFound.BranchTarget(VoidEnvelopeBranchNotFound))
			}
			if config.ProviderRejected.HasStep() {
				branches = append(branches, config.ProviderRejected.BranchTarget(VoidEnvelopeBranchProviderRejected))
			}
			if config.InvalidResponse.HasStep() {
				branches = append(branches, config.InvalidResponse.BranchTarget(VoidEnvelopeBranchInvalidResponse))
			}
			if config.Defect.HasStep() {
				branches = append(branches, config.Defect.BranchTarget(VoidEnvelopeBranchDefect))
			}
			return branches
		}(),
		ResultAttribute:     config.ResultAttribute,
		StepOptionsOverride: config.StepOptionsOverride,
	})
}

